                by[e["actor"]]["r3"] = (mv.get("status"), mv.get("terms", {}).get("unit_price"))
    # our sheets per thread: the buyer trace moves lack the supplier; use the session's moves list
    ours = {}
    for m in d.get("moves") or []:
        sid = m.get("supplier_id") or m.get("supplier")
